                                ? <StatsUsageComparisonTables rows={snapshot.rows} shortTokenCounts={controls.shortTokenCounts} />
                                : <StatsUsageComparisonCharts rows={snapshot.rows} shortTokenCounts={controls.shortTokenCounts} />
                            : isSmallScreen
